'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useAuth } from '@/hooks/useAuth';
import Navbar from '@/components/Navbar';

interface Task {
  id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  urgency: string;
  rewardPoints: number;
  createdAt: string;
  requester: {
    profile: {
      firstName: string;
      lastName: string;
    };
  };
  department: {
    name: string;
  };
}

export default function DashboardPage() {
  const { user, loading, refreshUser } = useAuth();
  const router = useRouter();
  const [myTasks, setMyTasks] = useState<Task[]>([]);
  const [acceptedTasks, setAcceptedTasks] = useState<Task[]>([]);
  const [loadingTasks, setLoadingTasks] = useState(true);

  useEffect(() => {
    if (!loading && !user) {
      router.push('/login');
      return;
    }

    if (user) {
      const loadDashboard = async () => {
        // Refresh to ensure points/level are up to date when navigating here
        if (refreshUser) {
          await refreshUser();
        }
        await fetchTasks();
      };
      loadDashboard();
    }
  }, [user?.id, loading, router, refreshUser]);

  const fetchTasks = async () => {
    try {
      const token = localStorage.getItem('token');
      const [myRes, acceptedRes] = await Promise.all([
        fetch('/api/tasks?myTasks=true', {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch('/api/tasks?acceptedByMe=true', {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ]);

      if (myRes.ok) {
        const data = await myRes.json();
        setMyTasks(data.filter((t: Task) => t.status !== 'COMPLETED' && t.status !== 'CANCELLED'));
      }

      if (acceptedRes.ok) {
        const data = await acceptedRes.json();
        setAcceptedTasks(data.filter((t: Task) => t.status === 'ACCEPTED'));
      }
    } catch (error) {
      console.error('Failed to fetch tasks:', error);
    } finally {
      setLoadingTasks(false);
    }
  };

  const getLevelColor = (level: string) => {
    switch (level) {
      case 'ELITE': return 'text-violet-600';
      case 'GOLD': return 'text-amber-600';
      case 'SILVER': return 'text-slate-600';
      case 'BRONZE': return 'text-orange-600';
      default: return 'text-slate-400';
    }
  };

  const getUrgencyColor = (urgency: string) => {
    switch (urgency) {
      case 'HIGH': return 'bg-red-100 text-red-800';
      case 'MEDIUM': return 'bg-amber-100 text-amber-800';
      default: return 'bg-emerald-100 text-emerald-800';
    }
  };

  const statCards = [
    { label: 'Points', value: user?.points ?? 0, icon: '≡ƒÆ░', delay: 0 },
    { label: 'Reputation', value: user?.reputation ?? 0, icon: 'Γ¡É', delay: 1 },
    { label: 'Level', value: user?.level ?? 'NEW', valueClass: getLevelColor(user?.level ?? ''), icon: '≡ƒÅå', delay: 2 },
    { label: 'Active Tasks', value: acceptedTasks.length, icon: '≡ƒôï', delay: 3 },
  ];

  if (loading || !user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
          <p className="text-sm font-medium text-slate-500">Loading...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="px-0 sm:px-0">
          <div className="mb-8 animate-fade-in-up">
            <h1 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
              Dashboard
            </h1>
            <p className="mt-1 text-slate-600">
              Welcome back, {user.profile?.firstName}!
            </p>
          </div>

          {/* Stats */}
          <div className="mb-8 grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {statCards.map((stat) => (
              <div
                key={stat.label}
                className="card-hover animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-5 shadow-card"
              >
                <div className="flex items-center gap-4">
                  <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary-50 text-2xl">
                    {stat.icon}
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium text-slate-500">{stat.label}</p>
                    <p className={`text-lg font-semibold text-slate-900 ${stat.valueClass ?? ''}`}>
                      {stat.value}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* Task lists */}
          <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
            <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white shadow-card">
              <div className="border-b border-slate-100 px-4 py-4 sm:px-6 sm:py-5">
                <h2 className="text-lg font-semibold text-slate-900">My Posted Tasks</h2>
              </div>
              <div className="p-4 sm:p-6">
                {loadingTasks ? (
                  <div className="flex justify-center py-8">
                    <div className="h-8 w-8 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
                  </div>
                ) : myTasks.length === 0 ? (
                  <p className="py-6 text-center text-slate-500">
                    No active tasks.{' '}
                    <Link href="/tasks/new" className="font-medium text-primary-600 hover:text-primary-700">
                      Post one now
                    </Link>
                  </p>
                ) : (
                  <ul className="space-y-4">
                    {myTasks.slice(0, 5).map((task) => (
                      <li key={task.id} className="border-b border-slate-100 pb-4 last:border-0 last:pb-0">
                        <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
                          <div className="min-w-0 flex-1">
                            <Link
                              href={`/tasks/${task.id}`}
                              className="font-medium text-slate-900 transition-colors hover:text-primary-600"
                            >
                              {task.title}
                            </Link>
                            <p className="mt-0.5 line-clamp-2 text-sm text-slate-500">
                              {task.description.substring(0, 100)}...
                            </p>
                            <div className="mt-2 flex flex-wrap items-center gap-2">
                              <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getUrgencyColor(task.urgency)}`}>
                                {task.urgency}
                              </span>
                              <span className="text-sm text-slate-500">{task.rewardPoints} pts</span>
                            </div>
                          </div>
                          <span className="shrink-0 text-sm text-slate-500 sm:ml-4">{task.status}</span>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>

            <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white shadow-card">
              <div className="border-b border-slate-100 px-4 py-4 sm:px-6 sm:py-5">
                <h2 className="text-lg font-semibold text-slate-900">Accepted Tasks</h2>
              </div>
              <div className="p-4 sm:p-6">
                {loadingTasks ? (
                  <div className="flex justify-center py-8">
                    <div className="h-8 w-8 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
                  </div>
                ) : acceptedTasks.length === 0 ? (
                  <p className="py-6 text-center text-slate-500">
                    No accepted tasks.{' '}
                    <Link href="/tasks" className="font-medium text-primary-600 hover:text-primary-700">
                      Browse tasks
                    </Link>
                  </p>
                ) : (
                  <ul className="space-y-4">
                    {acceptedTasks.map((task) => (
                      <li key={task.id} className="border-b border-slate-100 pb-4 last:border-0 last:pb-0">
                        <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
                          <div className="min-w-0 flex-1">
                            <Link
                              href={`/tasks/${task.id}`}
                              className="font-medium text-slate-900 transition-colors hover:text-primary-600"
                            >
                              {task.title}
                            </Link>
                            <p className="mt-0.5 line-clamp-2 text-sm text-slate-500">
                              {task.description.substring(0, 100)}...
                            </p>
                            <div className="mt-2 flex flex-wrap items-center gap-2">
                              <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getUrgencyColor(task.urgency)}`}>
                                {task.urgency}
                              </span>
                              <span className="text-sm text-slate-500">{task.rewardPoints} pts</span>
                            </div>
                          </div>
                          <Link
                            href={`/tasks/${task.id}`}
                            className="shrink-0 rounded-lg bg-primary-50 px-3 py-1.5 text-sm font-medium text-primary-700 transition-colors hover:bg-primary-100 sm:ml-4"
                          >
                            View
                          </Link>
                        </div>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/hooks/useAuth';
import Navbar from '@/components/Navbar';

interface LeaderboardEntry {
  rank: number;
  userId: string;
  email: string;
  firstName?: string;
  lastName?: string;
  reputation: number;
  points: number;
  level: string;
  department?: {
    name: string;
    code: string;
  };
  tasksCompleted: number;
  reputationChange?: number;
}

interface Department {
  id: string;
  name: string;
  code: string;
}

export default function LeaderboardPage() {
  const { user, loading } = useAuth();
  const router = useRouter();
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [type, setType] = useState<'all-time' | 'weekly' | 'department'>('all-time');
  const [selectedDepartment, setSelectedDepartment] = useState<string>('');
  const [loadingLeaderboard, setLoadingLeaderboard] = useState(true);

  useEffect(() => {
    if (!loading && !user) {
      router.push('/login');
      return;
    }

    if (user) {
      fetchDepartments();
      fetchLeaderboard();
    }
  }, [user, loading, router, type, selectedDepartment]);

  const fetchDepartments = async () => {
    try {
      const res = await fetch('/api/departments');
      if (res.ok) {
        const data = await res.json();
        setDepartments(data);
      }
    } catch (error) {
      console.error('Failed to fetch departments:', error);
    }
  };

  const fetchLeaderboard = async () => {
    setLoadingLeaderboard(true);
    try {
      const token = localStorage.getItem('token');
      const params = new URLSearchParams();
      params.append('type', type);
      if (type === 'department' && selectedDepartment) {
        params.append('departmentId', selectedDepartment);
      }

      const res = await fetch(`/api/leaderboard?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setLeaderboard(data.leaderboard || []);
      }
    } catch (error) {
      console.error('Failed to fetch leaderboard:', error);
    } finally {
      setLoadingLeaderboard(false);
    }
  };

  const getLevelColor = (level: string) => {
    switch (level) {
      case 'ELITE': return 'bg-violet-100 text-violet-700';
      case 'GOLD': return 'bg-amber-100 text-amber-700';
      case 'SILVER': return 'bg-slate-100 text-slate-700';
      case 'BRONZE': return 'bg-orange-100 text-orange-700';
      default: return 'bg-slate-50 text-slate-500';
    }
  };

  const getRankBadge = (rank: number) => {
    if (rank === 1) return '≡ƒÑç';
    if (rank === 2) return '≡ƒÑê';
    if (rank === 3) return '≡ƒÑë';
    return `#${rank}`;
  };

  const typeButtons: { id: typeof type; label: string }[] = [
    { id: 'all-time', label: 'All Time' },
    { id: 'weekly', label: 'Weekly' },
    { id: 'department', label: 'Department' },
  ];

  if (loading || !user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="px-0 sm:px-0">
          <h1 className="mb-6 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
            Leaderboard
          </h1>

          {/* Filters */}
          <div className="mb-6 animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-4 shadow-card sm:p-5">
            <div className="flex flex-wrap items-center gap-3 sm:gap-4">
              <div className="flex flex-wrap gap-2">
                {typeButtons.map((btn) => (
                  <button
                    key={btn.id}
                    onClick={() => setType(btn.id)}
                    className={`rounded-xl px-4 py-2 text-sm font-medium transition btn-active ${
                      type === btn.id
                        ? 'bg-primary-600 text-white shadow-soft'
                        : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                    }`}
                  >
                    {btn.label}
                  </button>
                ))}
              </div>
              {type === 'department' && (
                <select
                  value={selectedDepartment}
                  onChange={(e) => setSelectedDepartment(e.target.value)}
                  className="rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 shadow-sm focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                >
                  <option value="">Select Department</option>
                  {departments.map((dept) => (
                    <option key={dept.id} value={dept.id}>
                      {dept.name}
                    </option>
                  ))}
                </select>
              )}
            </div>
          </div>

          {/* Leaderboard - card on mobile, table on desktop */}
          {loadingLeaderboard ? (
            <div className="flex flex-col items-center justify-center py-16">
              <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
              <p className="mt-4 text-sm text-slate-500">Loading leaderboard...</p>
            </div>
          ) : leaderboard.length === 0 ? (
            <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-12 text-center shadow-card">
              <p className="text-slate-500">No leaderboard data available.</p>
            </div>
          ) : (
            <>
              {/* Mobile: cards */}
              <div className="space-y-3 sm:hidden">
                {leaderboard.map((entry) => (
                  <div
                    key={entry.userId}
                    className={`animate-fade-in-up rounded-2xl border p-4 shadow-card ${
                      entry.userId === user.id ? 'border-primary-200 bg-primary-50/50' : 'border-slate-200/80 bg-white'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-lg font-semibold text-slate-900">{getRankBadge(entry.rank)}</span>
                      <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${getLevelColor(entry.level)}`}>
                        {entry.level}
                      </span>
                    </div>
                    <p className="mt-1 font-medium text-slate-900">
                      {entry.firstName && entry.lastName ? `${entry.firstName} ${entry.lastName}` : entry.email}
                    </p>
                    <p className="text-xs text-slate-500">{entry.email}</p>
                    <div className="mt-3 flex flex-wrap gap-3 text-sm">
                      <span className="text-slate-600">{entry.reputation} rep</span>
                      <span className="text-slate-600">{entry.points} pts</span>
                      <span className="text-slate-600">{entry.tasksCompleted} tasks</span>
                      {type === 'weekly' && entry.reputationChange !== undefined && (
                        <span className={entry.reputationChange >= 0 ? 'text-emerald-600' : 'text-red-600'}>
                          {entry.reputationChange >= 0 ? '+' : ''}{entry.reputationChange}
                        </span>
                      )}
                    </div>
                    {entry.department?.name && (
                      <p className="mt-1 text-xs text-slate-500">{entry.department.name}</p>
                    )}
                  </div>
                ))}
              </div>

              {/* Desktop: table */}
              <div className="hidden overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-card sm:block">
                <table className="min-w-full divide-y divide-slate-200">
                  <thead className="bg-slate-50">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Rank
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        User
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Level
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Reputation
                      </th>
                      {type === 'weekly' && (
                        <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                          Change
                        </th>
                      )}
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Points
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Tasks
                      </th>
                      <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 sm:px-6">
                        Department
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-200 bg-white">
                    {leaderboard.map((entry) => (
                      <tr
                        key={entry.userId}
                        className={entry.userId === user.id ? 'bg-primary-50/50' : ''}
                      >
                        <td className="whitespace-nowrap px-4 py-4 text-sm font-medium text-slate-900 sm:px-6">
                          {getRankBadge(entry.rank)}
                        </td>
                        <td className="whitespace-nowrap px-4 py-4 sm:px-6">
                          <div className="text-sm font-medium text-slate-900">
                            {entry.firstName && entry.lastName ? `${entry.firstName} ${entry.lastName}` : entry.email}
                          </div>
                          <div className="text-sm text-slate-500">{entry.email}</div>
                        </td>
                        <td className="whitespace-nowrap px-4 py-4 sm:px-6">
                          <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getLevelColor(entry.level)}`}>
                            {entry.level}
                          </span>
                        </td>
                        <td className="whitespace-nowrap px-4 py-4 text-sm text-slate-900 sm:px-6">
                          {entry.reputation}
                        </td>
                        {type === 'weekly' && (
                          <td className="whitespace-nowrap px-4 py-4 text-sm sm:px-6">
                            {entry.reputationChange !== undefined && (
                              <span className={entry.reputationChange >= 0 ? 'text-emerald-600' : 'text-red-600'}>
                                {entry.reputationChange >= 0 ? '+' : ''}{entry.reputationChange}
                              </span>
                            )}
                          </td>
                        )}
                        <td className="whitespace-nowrap px-4 py-4 text-sm text-slate-900 sm:px-6">
                          {entry.points}
                        </td>
                        <td className="whitespace-nowrap px-4 py-4 text-sm text-slate-900 sm:px-6">
                          {entry.tasksCompleted}
                        </td>
                        <td className="whitespace-nowrap px-4 py-4 text-sm text-slate-500 sm:px-6">
                          {entry.department?.name || '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter, useParams } from 'next/navigation';
import Link from 'next/link';
import { useAuth } from '@/hooks/useAuth';
import Navbar from '@/components/Navbar';
import Chat from '@/components/Chat';
import RatingForm from '@/components/RatingForm';

interface Task {
  id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  urgency: string;
  rewardPoints: number;
  createdAt: string;
  locationText?: string;
  imageUrl?: string;
  requesterCompleted: boolean;
  acceptorCompleted: boolean;
  requester: {
    id: string;
    profile: {
      firstName: string;
      lastName: string;
    };
  };
  acceptor?: {
    id: string;
    profile: {
      firstName: string;
      lastName: string;
    };
  };
  department: {
    name: string;
  };
  ratings?: Array<{
    giverId: string;
    receiverId: string;
  }>;
}

export default function TaskDetailPage() {
  const { user, loading, refreshUser } = useAuth();
  const router = useRouter();
  const params = useParams();
  const [task, setTask] = useState<Task | null>(null);
  const [loadingTask, setLoadingTask] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [showChatHint, setShowChatHint] = useState(false);

  useEffect(() => {
    if (!loading && !user) {
      router.push('/login');
      return;
    }

    if (user && params.id) {
      fetchTask();
    }
  }, [user, loading, router, params.id]);

  const fetchTask = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/tasks/${params.id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setTask(data);
        setError(null);
        if (
          (data.status === 'ACCEPTED' || data.status === 'COMPLETED') &&
          user &&
          (data.requester.id === user.id || data.acceptor?.id === user.id)
        ) {
          setShowChatHint(true);
        } else {
          setShowChatHint(false);
        }
      } else if (res.status === 401) {
        router.push('/login');
      } else if (res.status === 403) {
        setError('You do not have access to view this task.');
      } else {
        setError('Task not found');
      }
    } catch (error) {
      console.error('Failed to fetch task:', error);
      setError('Connection error. Please try again.');
    } finally {
      setLoadingTask(false);
    }
  };

  useEffect(() => {
    if (!user || !params.id) return;
    const token = localStorage.getItem('token');
    if (!token) return;

    let socketUrl = '';
    if (typeof window !== 'undefined') {
      socketUrl = process.env.NEXT_PUBLIC_APP_URL || window.location.origin;
    }

    const { io } = require('socket.io-client');
    const socket = io(socketUrl, {
      auth: { token },
      path: '/socket.io',
      transports: ['polling', 'websocket'],
    });

    socket.on('connect', () => {
      socket.emit('join-task', params.id);
    });

    socket.on('task-completed', async (updatedTask: Task) => {
      setTask(updatedTask);
      await refreshUser();
      // Remove alert to ensure immediate redirection for the passive user
      router.push('/');
    });

    return () => {
      socket.emit('leave-task', params.id);
      socket.close();
    };
  }, [user, params.id, refreshUser, router]);

  const handleAccept = async () => {
    if (!task) return;
    setActionLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/tasks/${task.id}/accept`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        await fetchTask();
        setShowChatHint(true);
      } else {
        const errorData = await res.json();
        alert(errorData.error || 'Failed to accept task');
      }
    } catch (error) {
      console.error(error);
      alert('Failed to accept task. Check console for details.');
    } finally {
      setActionLoading(false);
    }
  };

  const handleComplete = async () => {
    if (!task) return;
    setActionLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/tasks/${task.id}/complete`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const updated = await res.json();
        setTask(updated);
        // If this call resulted in the task being fully completed and the current user is the worker,
        // refresh auth so points/reputation update instantly in the UI.
        if (updated.status === 'COMPLETED') {
          await refreshUser();
          router.push('/');
        } else {
          alert('Completion recorded. Once both sides confirm, rewards will be applied.');
        }
      } else {
        const errorData = await res.json();
        alert(errorData.error || 'Failed to complete task');
      }
    } catch (error) {
      alert('Failed to complete task');
    } finally {
      setActionLoading(false);
    }
  };

  const handleCancel = async () => {
    if (!task) return;
    if (!confirm('Are you sure you want to cancel this task?')) return;

    setActionLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/tasks/${task.id}/cancel`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        router.push('/tasks');
      } else {
        const errorData = await res.json();
        alert(errorData.error || 'Failed to cancel task');
      }
    } catch (error) {
      alert('Failed to cancel task');
    } finally {
      setActionLoading(false);
    }
  };

  if (loading || loadingTask) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
          <p className="text-sm text-slate-500">Loading task...</p>
        </div>
      </div>
    );
  }

  if (error || !task) {
    return (
      <div className="min-h-screen bg-slate-50">
        <Navbar />
        <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8">
          <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-8 text-center shadow-card">
            <h3 className="text-xl font-semibold text-slate-900">Task Not Found</h3>
            <p className="mt-2 text-slate-500">{error || 'This task may have been removed or does not exist.'}</p>
            <Link
              href="/tasks"
              className="mt-6 inline-flex items-center rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white shadow-soft transition hover:bg-primary-700"
            >
              Back to Tasks
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const isRequester = user && task.requester.id === user.id;
  const isAcceptor = user && task.acceptor?.id === user.id;
  const canAccept = task.status === 'OPEN' && !isRequester;
  const canComplete =
    task.status === 'ACCEPTED' &&
    ((isRequester && !task.requesterCompleted) || (isAcceptor && !task.acceptorCompleted));
  const showChat = (task.status === 'ACCEPTED' || task.status === 'COMPLETED') && (isRequester || isAcceptor);

  const urgencyClass =
    task.urgency === 'HIGH' ? 'bg-red-100 text-red-800' :
    task.urgency === 'MEDIUM' ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800';

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="px-0 sm:px-0">
          <Link
            href="/tasks"
            className="mb-4 inline-flex items-center text-sm font-medium text-primary-600 transition-colors hover:text-primary-700"
          >
            ΓåÉ Back to Tasks
          </Link>

          <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-4 shadow-card sm:p-6 lg:p-8">
            <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-start md:justify-between">
              <div>
                <h1 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">{task.title}</h1>
                <div className="mt-2 flex flex-wrap items-center gap-2">
                  <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${urgencyClass}`}>
                    {task.urgency}
                  </span>
                  <span className="inline-flex items-center rounded-full bg-slate-100 px-2.5 py-0.5 text-xs font-medium text-slate-800">
                    {task.category}
                  </span>
                  <span className="text-sm text-slate-500">{task.department.name}</span>
                </div>
              </div>
              <div className="flex shrink-0 flex-col items-start md:items-end">
                <div className="text-2xl font-bold text-primary-600">{task.rewardPoints} pts</div>
                <div className="mt-1 text-sm font-medium uppercase tracking-wider text-slate-500">{task.status}</div>
              </div>
            </div>

            <div className="mb-6">
              <h2 className="text-lg font-semibold text-slate-900">Description</h2>
              <p className="mt-2 whitespace-pre-wrap text-slate-700">{task.description}</p>
            </div>

            {(task.locationText || task.imageUrl) && (
              <div className="mb-6 grid grid-cols-1 gap-6 md:grid-cols-2">
                {task.locationText && (
                  <div>
                    <h2 className="text-lg font-semibold text-slate-900">Location</h2>
                    <p className="mt-2 text-slate-700">{task.locationText}</p>
                  </div>
                )}
                {task.imageUrl && (
                  <div>
                    <h2 className="text-lg font-semibold text-slate-900">Image</h2>
                    <img src={task.imageUrl} alt={task.title} className="mt-2 max-w-full rounded-xl object-cover shadow-card" />
                  </div>
                )}
              </div>
            )}

            <div className="flex flex-col gap-4 rounded-xl border-t border-slate-200 bg-slate-50/50 p-4 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
              <div className="flex flex-wrap gap-6">
                <div>
                  <p className="text-sm text-slate-500">Posted by</p>
                  <p className="font-medium text-slate-900">
                    {task.requester.profile.firstName} {task.requester.profile.lastName}
                    {isRequester && <span className="ml-1 text-xs font-medium text-primary-600">(You)</span>}
                  </p>
                  {isRequester && task.status === 'ACCEPTED' && (
                    <p className="mt-1 text-xs text-slate-500">
                      {task.requesterCompleted
                        ? task.acceptorCompleted
                          ? 'Both sides have confirmed completion.'
                          : 'You have confirmed completion. Waiting for the helper to confirm.'
                        : 'Confirm completion once the task is done. Both sides must confirm.'}
                    </p>
                  )}
                </div>
                {task.acceptor && (
                  <div>
                    <p className="text-sm text-slate-500">Accepted by</p>
                    <p className="font-medium text-slate-900">
                      {task.acceptor.profile.firstName} {task.acceptor.profile.lastName}
                      {isAcceptor && <span className="ml-1 text-xs font-medium text-primary-600">(You)</span>}
                    </p>
                    {isAcceptor && task.status === 'ACCEPTED' && (
                      <p className="mt-1 text-xs text-slate-500">
                        {task.acceptorCompleted
                          ? task.requesterCompleted
                            ? 'Both sides have confirmed completion.'
                            : 'You have confirmed completion. Waiting for the poster to confirm.'
                          : 'Confirm completion once you have finished the task. Both sides must confirm.'}
                      </p>
                    )}
                  </div>
                )}
              </div>
              <div className="flex flex-wrap gap-3">
                {canAccept && (
                  <button
                    onClick={handleAccept}
                    disabled={actionLoading}
                    className="rounded-xl bg-primary-600 px-6 py-2.5 font-medium text-white shadow-soft transition hover:bg-primary-700 disabled:opacity-50 btn-active"
                  >
                    Accept Task
                  </button>
                )}
                {canComplete && (
                  <button
                    onClick={handleComplete}
                    disabled={actionLoading}
                    className="rounded-xl bg-emerald-600 px-6 py-2.5 font-medium text-white shadow-soft transition hover:bg-emerald-700 disabled:opacity-50 btn-active"
                  >
                    Mark Complete
                  </button>
                )}
                {(isRequester || isAcceptor) && task.status !== 'COMPLETED' && task.status !== 'CANCELLED' && (
                  <button
                    onClick={handleCancel}
                    disabled={actionLoading}
                    className="rounded-xl border border-red-200 bg-white px-6 py-2.5 font-medium text-red-700 shadow-card transition hover:bg-red-50 disabled:opacity-50 btn-active"
                  >
                    Cancel Task
                  </button>
                )}
              </div>
            </div>
          </div>

          {showChat && (
            <div className="mt-8 animate-fade-in-up">
              <h2 className="mb-4 text-xl font-bold text-slate-900">Task Chat</h2>
              {showChatHint && (
                <div className="mb-4 flex gap-3 rounded-xl border border-sky-200 bg-sky-50 p-4">
                  <div className="shrink-0 text-sky-500">
                    <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                    </svg>
                  </div>
                  <p className="text-sm text-sky-800">
                    You can now chat with {isRequester ? task.acceptor?.profile.firstName : task.requester.profile.firstName} to coordinate this task.
                  </p>
                </div>
              )}
              <Chat
                taskId={task.id}
                requesterId={task.requester.id}
                acceptorId={task.acceptor?.id || ''}
              />
            </div>
          )}

          {task.status === 'COMPLETED' && task.acceptor && (
            <div className="mt-8 animate-fade-in-up">
              <h2 className="mb-4 text-xl font-bold text-slate-900">Ratings</h2>
              <div className="grid grid-cols-1 gap-6 md:grid-cols-2">
                {isRequester && (!task.ratings || !task.ratings.some(r => r.giverId === user?.id && r.receiverId === task.acceptor!.id)) && (
                  <RatingForm
                    taskId={task.id}
                    receiverId={task.acceptor.id}
                    receiverName={`${task.acceptor.profile.firstName} ${task.acceptor.profile.lastName}`}
                    onRated={() => fetchTask()}
                  />
                )}
                {isAcceptor && (!task.ratings || !task.ratings.some(r => r.giverId === user?.id && r.receiverId === task.requester.id)) && (
                  <RatingForm
                    taskId={task.id}
                    receiverId={task.requester.id}
                    receiverName={`${task.requester.profile.firstName} ${task.requester.profile.lastName}`}
                    onRated={() => fetchTask()}
                  />
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/hooks/useAuth';
import Navbar from '@/components/Navbar';
import { z } from 'zod';

interface Department {
  id: string;
  name: string;
  code: string;
}

const createTaskSchema = z.object({
  title: z.string().min(1, 'Title is required').max(200, 'Title matches max length of 200'),
  description: z.string().min(1, 'Description is required').max(2000, 'Description matches max length of 2000'),
  category: z.enum(['ERRAND', 'LOST', 'BOOK', 'TUTORING', 'OTHER']),
  departmentId: z.string().min(1, 'Department is required'),
  urgency: z.enum(['LOW', 'MEDIUM', 'HIGH']),
  rewardPoints: z.number().int().min(1, 'Points must be at least 1').max(100, 'Points cannot exceed 100'),
  locationText: z.string().optional(),
  imageUrl: z.string().optional(),
});

type TaskFormData = z.infer<typeof createTaskSchema>;

export default function NewTaskPage() {
  const { user, loading } = useAuth();
  const router = useRouter();
  const [departments, setDepartments] = useState<Department[]>([]);
  const [formData, setFormData] = useState<TaskFormData>({
    title: '',
    description: '',
    category: 'ERRAND',
    departmentId: '',
    urgency: 'MEDIUM',
    rewardPoints: 15,
    locationText: '',
    imageUrl: '',
  });
  const [fieldErrors, setFieldErrors] = useState<Partial<Record<keyof TaskFormData, string>>>({});
  const [generalError, setGeneralError] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);

  useEffect(() => {
    if (!loading && !user) {
      router.push('/login');
      return;
    }

    if (user) {
      if (user.level === 'NEW') {
        alert('You need to reach Bronze level to post tasks. Complete tasks to earn reputation!');
        router.push('/tasks');
        return;
      }
      fetchDepartments();
    }
  }, [user, loading, router]);

  useEffect(() => {
    if (user?.department?.id) {
      setFormData((prev) => ({ ...prev, departmentId: user.department!.id }));
    }
  }, [user]);

  const fetchDepartments = async () => {
    try {
      const res = await fetch('/api/departments');
      if (res.ok) {
        const data = await res.json();
        setDepartments(data);
        if (!formData.departmentId && data.length > 0 && !user?.department?.id) {
          setFormData((prev) => ({ ...prev, departmentId: data[0].id }));
        }
      }
    } catch (error) {
      console.error('Failed to fetch departments:', error);
    }
  };

  const validateForm = (): boolean => {
    try {
      createTaskSchema.parse(formData);
      setFieldErrors({});
      return true;
    } catch (error) {
      if (error instanceof z.ZodError) {
        const errors: Partial<Record<keyof TaskFormData, string>> = {};
        error.errors.forEach((err) => {
          if (err.path[0]) {
            errors[err.path[0] as keyof TaskFormData] = err.message;
          }
        });
        setFieldErrors(errors);
      }
      return false;
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setGeneralError('');

    if (!validateForm()) {
      setGeneralError('Please fix the errors below.');
      return;
    }

    setSubmitting(true);

    try {
      const token = localStorage.getItem('token');
      const dataToSend = {
        ...formData,
        imageUrl: formData.imageUrl === '' ? undefined : formData.imageUrl,
        locationText: formData.locationText === '' ? undefined : formData.locationText,
      };

      const res = await fetch('/api/tasks', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(dataToSend),
      });

      if (res.ok) {
        const task = await res.json();
        router.push(`/tasks/${task.id}`);
      } else {
        const errorData = await res.json();
        if (errorData.details) {
          const errors: Partial<Record<keyof TaskFormData, string>> = {};
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          errorData.details.forEach((err: any) => {
            if (err.path[0]) {
              errors[err.path[0] as keyof TaskFormData] = err.message;
            }
          });
          setFieldErrors(errors);
          setGeneralError('Invalid input. Please check the fields.');
        } else {
          setGeneralError(errorData.error || 'Failed to create task');
        }
      }
    } catch (error) {
      setGeneralError('Failed to create task');
    } finally {
      setSubmitting(false);
    }
  };

  const inputBase = 'block w-full rounded-xl border bg-white px-4 py-2.5 text-slate-900 shadow-sm transition focus:outline-none focus:ring-2 sm:text-sm';
  const inputError = 'border-red-300 focus:border-red-500 focus:ring-red-500/20';
  const inputNormal = 'border-slate-300 focus:border-primary-500 focus:ring-primary-500/20';

  const inputClassName = (fieldName: keyof TaskFormData) =>
    `${inputBase} ${fieldErrors[fieldName] ? inputError : inputNormal}`;

  if (loading || !user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      <div className="mx-auto max-w-3xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="px-0 sm:px-0">
          <h1 className="mb-6 text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
            Create New Task
          </h1>

          <form
            onSubmit={handleSubmit}
            className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-4 shadow-card sm:p-6 lg:p-8"
          >
            {generalError && (
              <div className="mb-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700" role="alert">
                {generalError}
              </div>
            )}

            <div className="space-y-5 sm:space-y-6">
              <div>
                <label htmlFor="title" className="mb-1 block text-sm font-medium text-slate-700">
                  Title *
                </label>
                <input
                  type="text"
                  id="title"
                  maxLength={200}
                  className={inputClassName('title')}
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                />
                {fieldErrors.title && <p className="mt-1 text-sm text-red-600">{fieldErrors.title}</p>}
              </div>

              <div>
                <label htmlFor="description" className="mb-1 block text-sm font-medium text-slate-700">
                  Description *
                </label>
                <textarea
                  id="description"
                  rows={6}
                  maxLength={2000}
                  className={inputClassName('description')}
                  value={formData.description}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                />
                {fieldErrors.description && <p className="mt-1 text-sm text-red-600">{fieldErrors.description}</p>}
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label htmlFor="category" className="mb-1 block text-sm font-medium text-slate-700">
                    Category *
                  </label>
                  <select
                    id="category"
                    required
                    className={inputClassName('category')}
                    value={formData.category}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value as TaskFormData['category'] })}
                  >
                    <option value="ERRAND">Errand</option>
                    <option value="LOST">Lost & Found</option>
                    <option value="BOOK">Book Exchange</option>
                    <option value="TUTORING">Tutoring</option>
                    <option value="OTHER">Other</option>
                  </select>
                  {fieldErrors.category && <p className="mt-1 text-sm text-red-600">{fieldErrors.category}</p>}
                </div>
                <div>
                  <label htmlFor="departmentId" className="mb-1 block text-sm font-medium text-slate-700">
                    Department *
                  </label>
                  <select
                    id="departmentId"
                    required
                    className={inputClassName('departmentId')}
                    value={formData.departmentId}
                    onChange={(e) => setFormData({ ...formData, departmentId: e.target.value })}
                  >
                    {departments.map((dept) => (
                      <option key={dept.id} value={dept.id}>
                        {dept.name}
                      </option>
                    ))}
                  </select>
                  {fieldErrors.departmentId && <p className="mt-1 text-sm text-red-600">{fieldErrors.departmentId}</p>}
                </div>
              </div>

              <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                <div>
                  <label htmlFor="urgency" className="mb-1 block text-sm font-medium text-slate-700">
                    Urgency *
                  </label>
                  <select
                    id="urgency"
                    required
                    className={inputClassName('urgency')}
                    value={formData.urgency}
                    onChange={(e) => setFormData({ ...formData, urgency: e.target.value as TaskFormData['urgency'] })}
                  >
                    <option value="LOW">Low</option>
                    <option value="MEDIUM">Medium</option>
                    <option value="HIGH">High</option>
                  </select>
                  {fieldErrors.urgency && <p className="mt-1 text-sm text-red-600">{fieldErrors.urgency}</p>}
                </div>
                <div>
                  <label htmlFor="rewardPoints" className="mb-1 block text-sm font-medium text-slate-700">
                    Reward Points *
                  </label>
                  <input
                    type="number"
                    id="rewardPoints"
                    required
                    min={1}
                    max={100}
                    className={inputClassName('rewardPoints')}
                    value={formData.rewardPoints}
                    onChange={(e) => setFormData({ ...formData, rewardPoints: parseInt(e.target.value) || 0 })}
                  />
                  <p className="mt-1 text-sm text-slate-500">You will pay 10 points to post this task</p>
                  {fieldErrors.rewardPoints && <p className="mt-1 text-sm text-red-600">{fieldErrors.rewardPoints}</p>}
                </div>
              </div>

              <div>
                <label htmlFor="locationText" className="mb-1 block text-sm font-medium text-slate-700">
                  Location <span className="text-slate-400">(optional)</span>
                </label>
                <input
                  type="text"
                  id="locationText"
                  className={inputClassName('locationText')}
                  value={formData.locationText}
                  onChange={(e) => setFormData({ ...formData, locationText: e.target.value })}
                />
                {fieldErrors.locationText && <p className="mt-1 text-sm text-red-600">{fieldErrors.locationText}</p>}
              </div>

              <div>
                <label htmlFor="image" className="mb-1 block text-sm font-medium text-slate-700">
                  Image <span className="text-slate-400">(optional)</span>
                </label>
                <input
                  id="image"
                  type="file"
                  accept="image/*"
                  className="block w-full text-sm text-slate-600 file:mr-3 file:rounded-lg file:border-0 file:bg-slate-100 file:px-3 file:py-2 file:text-sm file:font-medium file:text-slate-700 hover:file:bg-slate-200"
                  onChange={async (e) => {
                    const file = e.target.files?.[0];
                    if (!file) return;
                    setUploadingImage(true);
                    setFieldErrors((prev) => ({ ...prev, imageUrl: undefined }));
                    try {
                      const form = new FormData();
                      form.append('file', file);
                      const res = await fetch('/api/upload', {
                        method: 'POST',
                        body: form,
                      });
                      if (!res.ok) {
                        const err = await res.json().catch(() => ({}));
                        setFieldErrors((prev) => ({
                          ...prev,
                          imageUrl: err.error || 'Failed to upload image',
                        }));
                        return;
                      }
                      const { url } = await res.json();
                      setFormData((prev) => ({ ...prev, imageUrl: url }));
                    } catch {
                      setFieldErrors((prev) => ({
                        ...prev,
                        imageUrl: 'Failed to upload image',
                      }));
                    } finally {
                      setUploadingImage(false);
                    }
                  }}
                />
                {uploadingImage && (
                  <p className="mt-1 text-xs text-slate-500">Uploading image...</p>
                )}
                {formData.imageUrl && !fieldErrors.imageUrl && (
                  <div className="mt-2">
                    <p className="mb-1 text-xs font-medium text-slate-500">Preview</p>
                    <img
                      src={formData.imageUrl}
                      alt="Preview"
                      className="max-h-40 rounded-lg border border-slate-200 object-cover"
                    />
                  </div>
                )}
                {fieldErrors.imageUrl && (
                  <p className="mt-1 text-sm text-red-600">{fieldErrors.imageUrl}</p>
                )}
              </div>
            </div>

            <div className="mt-6 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end sm:gap-3">
              <button
                type="button"
                onClick={() => router.back()}
                className="rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-sm font-medium text-slate-700 shadow-sm transition hover:bg-slate-50"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={submitting}
                className="rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white shadow-soft transition hover:bg-primary-700 disabled:opacity-50 btn-active"
              >
                {submitting ? 'Creating...' : 'Create Task'}
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import Link from 'next/link';
import { useAuth } from '@/hooks/useAuth';
import Navbar from '@/components/Navbar';

interface Task {
  id: string;
  title: string;
  description: string;
  category: string;
  status: string;
  urgency: string;
  rewardPoints: number;
  createdAt: string;
  requester: {
    profile: {
      firstName: string;
      lastName: string;
    };
  };
  department: {
    name: string;
    code: string;
  };
  isFeatured: boolean;
  isBoosted: boolean;
}

interface Department {
  id: string;
  name: string;
  code: string;
}

type TabType = 'feed' | 'active' | 'my-posts';

export default function TasksPage() {
  const { user, loading } = useAuth();
  const router = useRouter();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [selectedDepartment, setSelectedDepartment] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('');
  const [activeTab, setActiveTab] = useState<TabType>('feed');
  const [loadingTasks, setLoadingTasks] = useState(true);

  useEffect(() => {
    if (!loading && !user) {
      router.push('/login');
      return;
    }

    if (user) {
      fetchDepartments();
      fetchTasks();
    }
  }, [user, loading, router, selectedDepartment, selectedCategory, activeTab]);

  const fetchDepartments = async () => {
    try {
      const res = await fetch('/api/departments');
      if (res.ok) {
        const data = await res.json();
        setDepartments(data);
      }
    } catch (error) {
      console.error('Failed to fetch departments:', error);
    }
  };

  const fetchTasks = async () => {
    setLoadingTasks(true);
    try {
      const token = localStorage.getItem('token');
      const params = new URLSearchParams();

      if (selectedDepartment) params.append('departmentId', selectedDepartment);
      if (selectedCategory) params.append('category', selectedCategory);

      if (activeTab === 'feed') {
        params.append('status', 'OPEN');
      } else if (activeTab === 'active') {
        params.append('acceptedByMe', 'true');
        params.append('status', 'ACCEPTED');
      } else if (activeTab === 'my-posts') {
        params.append('myTasks', 'true');
      }

      const res = await fetch(`/api/tasks?${params.toString()}`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.ok) {
        const data = await res.json();
        setTasks(data);
      }
    } catch (error) {
      console.error('Failed to fetch tasks:', error);
    } finally {
      setLoadingTasks(false);
    }
  };

  const getUrgencyColor = (urgency: string) => {
    switch (urgency) {
      case 'HIGH': return 'bg-red-100 text-red-800';
      case 'MEDIUM': return 'bg-amber-100 text-amber-800';
      default: return 'bg-emerald-100 text-emerald-800';
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'ERRAND': return 'bg-sky-100 text-sky-800';
      case 'LOST': return 'bg-violet-100 text-violet-800';
      case 'BOOK': return 'bg-emerald-100 text-emerald-800';
      case 'TUTORING': return 'bg-indigo-100 text-indigo-800';
      default: return 'bg-slate-100 text-slate-800';
    }
  };

  const tabs: { id: TabType; label: string }[] = [
    { id: 'feed', label: 'Available Tasks' },
    { id: 'active', label: 'Active Tasks' },
    { id: 'my-posts', label: 'My Posts' },
  ];

  if (loading || !user) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-slate-50">
        <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50">
      <Navbar />
      <div className="mx-auto max-w-7xl px-4 py-6 sm:px-6 lg:px-8">
        <div className="px-0 sm:px-0">
          <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
            <h1 className="text-2xl font-bold tracking-tight text-slate-900 sm:text-3xl">
              Task Feed
            </h1>
            <Link
              href="/tasks/new"
              className="inline-flex w-full justify-center items-center rounded-xl bg-primary-600 px-4 py-2.5 text-sm font-semibold text-white shadow-soft transition hover:bg-primary-700 focus:outline-none focus:ring-2 focus:ring-primary-500 focus:ring-offset-2 sm:w-auto btn-active"
            >
              + New Task
            </Link>
          </div>

          {/* Tabs - scroll on mobile */}
          <div className="mb-6 overflow-x-auto scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
            <nav className="flex min-w-max gap-1 border-b border-slate-200 sm:gap-2" aria-label="Tabs">
              {tabs.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`whitespace-nowrap border-b-2 px-3 py-3.5 text-sm font-medium transition-colors sm:px-4 ${
                    activeTab === tab.id
                      ? 'border-primary-500 text-primary-600'
                      : 'border-transparent text-slate-500 hover:border-slate-300 hover:text-slate-700'
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </nav>
          </div>

          {/* Filters */}
          <div className="mb-6 animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-4 shadow-card sm:p-5">
            <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700">Department</label>
                <select
                  value={selectedDepartment}
                  onChange={(e) => setSelectedDepartment(e.target.value)}
                  className="block w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-slate-900 shadow-sm focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 sm:text-sm"
                >
                  <option value="">All Departments</option>
                  {departments.map((dept) => (
                    <option key={dept.id} value={dept.id}>
                      {dept.name}
                    </option>
                  ))}
                </select>
              </div>
              <div>
                <label className="mb-1 block text-sm font-medium text-slate-700">Category</label>
                <select
                  value={selectedCategory}
                  onChange={(e) => setSelectedCategory(e.target.value)}
                  className="block w-full rounded-xl border border-slate-300 bg-white px-3 py-2.5 text-slate-900 shadow-sm focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 sm:text-sm"
                >
                  <option value="">All Categories</option>
                  <option value="ERRAND">Errand</option>
                  <option value="LOST">Lost & Found</option>
                  <option value="BOOK">Book Exchange</option>
                  <option value="TUTORING">Tutoring</option>
                  <option value="OTHER">Other</option>
                </select>
              </div>
              <div className="flex items-end">
                <button
                  type="button"
                  onClick={() => {
                    setSelectedDepartment('');
                    setSelectedCategory('');
                  }}
                  className="w-full rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-sm font-medium text-slate-700 shadow-sm transition hover:bg-slate-50"
                >
                  Clear Filters
                </button>
              </div>
            </div>
          </div>

          {/* Task List */}
          {loadingTasks ? (
            <div className="flex flex-col items-center justify-center py-16">
              <div className="h-12 w-12 animate-spin rounded-full border-2 border-slate-200 border-t-primary-600" />
              <p className="mt-4 text-sm text-slate-500">Loading tasks...</p>
            </div>
          ) : tasks.length === 0 ? (
            <div className="animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-12 text-center shadow-card">
              <p className="text-slate-500">
                {activeTab === 'feed'
                  ? 'No available tasks found.'
                  : activeTab === 'active'
                  ? "You haven't accepted any tasks yet."
                  : "You haven't posted any tasks yet."}
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 gap-4 sm:gap-6">
              {tasks.map((task, i) => (
                <Link
                  key={task.id}
                  href={`/tasks/${task.id}`}
                  className="card-hover animate-fade-in-up rounded-2xl border border-slate-200/80 bg-white p-4 shadow-card transition-all hover:border-slate-200 sm:p-6"
                >
                  <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                    <div className="min-w-0 flex-1">
                      <div className="mb-2 flex flex-wrap items-center gap-2">
                        {task.isFeatured && (
                          <span className="inline-flex items-center rounded-full bg-amber-100 px-2.5 py-0.5 text-xs font-medium text-amber-800">
                            Γ¡É Featured
                          </span>
                        )}
                        {task.isBoosted && (
                          <span className="inline-flex items-center rounded-full bg-violet-100 px-2.5 py-0.5 text-xs font-medium text-violet-800">
                            ≡ƒÜÇ Boosted
                          </span>
                        )}
                        <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getUrgencyColor(task.urgency)}`}>
                          {task.urgency}
                        </span>
                        <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium ${getCategoryColor(task.category)}`}>
                          {task.category}
                        </span>
                      </div>
                      <h3 className="text-lg font-semibold text-slate-900 sm:text-xl">{task.title}</h3>
                      <p className="mt-1 line-clamp-2 text-slate-600 sm:line-clamp-3">{task.description}</p>
                      <div className="mt-3 flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-slate-500">
                        <span>By {task.requester.profile.firstName} {task.requester.profile.lastName}</span>
                        <span>┬╖</span>
                        <span>{task.department.name}</span>
                        <span>┬╖</span>
                        <span className="font-medium text-primary-600">{task.rewardPoints} points</span>
                      </div>
                    </div>
                    <div className="flex shrink-0 flex-col items-end gap-2 sm:ml-4">
                      <div className="text-sm text-slate-500">
                        {new Date(task.createdAt).toLocaleDateString()}
                      </div>
                      <span className={`inline-flex items-center rounded-full px-3 py-1 text-xs font-medium ${
                        task.status === 'OPEN' ? 'bg-emerald-100 text-emerald-800' : 'bg-sky-100 text-sky-800'
                      }`}>
                        {task.status}
                      </span>
                    </div>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useState, useRef } from 'react';
import { io, Socket } from 'socket.io-client';
import { useAuth } from '@/hooks/useAuth';

interface Message {
  id: string;
  content: string;
  senderId: string;
  receiverId: string;
  createdAt: string;
  sender: {
    profile: {
      firstName: string;
      lastName: string;
    };
  };
}

interface ChatProps {
  taskId: string;
  requesterId: string;
  acceptorId: string;
}

const POLL_INTERVAL_MS = 3000;
const SOCKET_TIMEOUT_MS = 4000;

export default function Chat({ taskId, requesterId, acceptorId }: ChatProps) {
  const { user } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [socket, setSocket] = useState<Socket | null>(null);
  const [connected, setConnected] = useState(false);
  const [useFallback, setUseFallback] = useState(false);
  const [sendLoading, setSendLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [autoScroll, setAutoScroll] = useState(true);

  const fetchMessages = async () => {
    try {
      const token = localStorage.getItem('token');
      const res = await fetch(`/api/messages?taskId=${taskId}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setMessages(data);
      }
    } catch (error) {
      console.error('Failed to fetch messages:', error);
    }
  };

  const scrollToBottom = () => {
    if (!autoScroll) return;
    if (containerRef.current) {
      containerRef.current.scrollTo({
        top: containerRef.current.scrollHeight,
        behavior: 'smooth',
      });
    }
  };

  useEffect(() => {
    if (!user) return;

    const token = localStorage.getItem('token');
    if (!token) return;

    fetchMessages();

    const socketUrl =
      typeof window !== 'undefined'
        ? (process.env.NEXT_PUBLIC_APP_URL || window.location.origin)
        : 'http://localhost:3000';

    const newSocket = io(socketUrl, {
      auth: { token },
      path: '/socket.io',
      transports: ['polling', 'websocket'],
      reconnection: true,
      reconnectionAttempts: 3,
      reconnectionDelay: 1000,
      timeout: 5000,
    });

    const timeoutId = setTimeout(() => {
      if (!newSocket.connected) {
        console.warn('Socket did not connect in time, using REST fallback');
        setUseFallback(true);
        newSocket.close();
      }
    }, SOCKET_TIMEOUT_MS);

    newSocket.on('connect', () => {
      clearTimeout(timeoutId);
      setConnected(true);
      setUseFallback(false);
      newSocket.emit('join-task', taskId);
    });

    newSocket.on('joined-task', () => {
      fetchMessages();
    });

    newSocket.on('new-message', (message: Message) => {
      setMessages((prev) => [...prev, message]);
    });

    newSocket.on('disconnect', () => {
      setConnected(false);
    });

    newSocket.on('connect_error', (err) => {
      console.warn('[Chat] Socket connect_error:', err.message);
      clearTimeout(timeoutId);
      setUseFallback(true);
    });

    setSocket(newSocket);

    return () => {
      clearTimeout(timeoutId);
      newSocket.emit('leave-task', taskId);
      newSocket.close();
    };
  }, [taskId, user?.id]);

  useEffect(() => {
    if (connected) return;
    const interval = setInterval(fetchMessages, POLL_INTERVAL_MS);
    return () => clearInterval(interval);
  }, [connected, taskId]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleScroll = () => {
    const container = containerRef.current;
    if (!container) return;
    const { scrollTop, scrollHeight, clientHeight } = container;
    const distanceFromBottom = scrollHeight - (scrollTop + clientHeight);
    // If user is within 40px of the bottom, keep auto-scroll enabled
    setAutoScroll(distanceFromBottom < 40);
  };

  const canSend = !!user;
  const otherPartyId = user?.id === requesterId ? acceptorId : requesterId;

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    const content = newMessage.trim();
    if (!content) return;

    if (connected && socket) {
      socket.emit('send-message', {
        taskId,
        receiverId: otherPartyId,
        content,
      });
      setNewMessage('');
      return;
    }

    setSendLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res = await fetch('/api/messages', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          taskId,
          receiverId: otherPartyId,
          content,
        }),
      });
      if (res.ok) {
        setNewMessage('');
        await fetchMessages();
      }
    } finally {
      setSendLoading(false);
    }
  };

  const isRequester = user?.id === requesterId;
  const otherPartyName = isRequester
    ? messages.find((m) => m.senderId === acceptorId)?.sender?.profile?.firstName || 'Acceptor'
    : messages.find((m) => m.senderId === requesterId)?.sender?.profile?.firstName || 'Requester';

  const statusText = connected
    ? 'Realtime'
    : useFallback
      ? 'Chat (polling)'
      : 'ConnectingΓÇª (you can still send messages)';

  const statusColor = connected ? 'text-emerald-600' : useFallback ? 'text-slate-500' : 'text-amber-600';

  return (
    <div className="animate-fade-in-up overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-card">
      <div className="border-b border-slate-100 px-4 py-3 sm:px-5">
        <h3 className="text-lg font-semibold text-slate-900">Chat</h3>
        <p className="text-sm text-slate-500">Chatting with {otherPartyName}</p>
        <p className={`mt-1 text-xs font-medium ${statusColor}`}>{statusText}</p>
      </div>

      <div
        ref={containerRef}
        className="h-72 overflow-y-auto p-4 sm:h-96 sm:p-5"
        onScroll={handleScroll}
      >
        {messages.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center py-8 text-center text-slate-500">
            <p>No messages yet.</p>
            <p className="mt-1 text-sm">Start the conversation!</p>
          </div>
        ) : (
          <div className="space-y-4">
            {messages.map((message) => {
              const isOwnMessage = message.senderId === user?.id;
              return (
                <div
                  key={message.id}
                  className={`flex animate-fade-in ${isOwnMessage ? 'justify-end' : 'justify-start'}`}
                >
                  <div
                    className={`max-w-[85%] sm:max-w-md rounded-2xl px-4 py-2.5 shadow-card ${
                      isOwnMessage
                        ? 'rounded-br-md bg-primary-600 text-white'
                        : 'rounded-bl-md bg-slate-100 text-slate-900'
                    }`}
                  >
                    <p className="text-sm leading-relaxed">{message.content}</p>
                    <p
                      className={`mt-1 text-xs ${
                        isOwnMessage ? 'text-primary-100' : 'text-slate-500'
                      }`}
                    >
                      {new Date(message.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </p>
                  </div>
                </div>
              );
            })}
            <div ref={messagesEndRef} />
          </div>
        )}
      </div>

      <form onSubmit={handleSendMessage} className="border-t border-slate-100 px-4 py-3 sm:px-5">
        <div className="flex gap-2">
          <input
            type="text"
            value={newMessage}
            onChange={(e) => setNewMessage(e.target.value)}
            placeholder="Type a message..."
            className="flex-1 rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-slate-900 placeholder-slate-400 shadow-sm transition focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20 sm:text-sm"
            disabled={!canSend}
          />
          <button
            type="submit"
            disabled={!canSend || !newMessage.trim() || sendLoading}
            className="shrink-0 rounded-xl bg-primary-600 px-4 py-2.5 font-medium text-white shadow-soft transition hover:bg-primary-700 disabled:opacity-50 disabled:cursor-not-allowed btn-active sm:px-5"
          >
            {sendLoading ? 'SendingΓÇª' : 'Send'}
          </button>
        </div>
      </form>
    </div>
  );
}
